3	import { createClient } from "@/lib/supabase/server";
4	import { signItemImages, displayPath } from "@/lib/storage/signed";
5	import { fetchForecast } from "@/lib/weather/open-meteo";
6	import { laterAdvice } from "@/lib/weather/advice";
7	import { occasionBand, applyFormalityOverride } from "@/lib/generator/rules";
8	import { buildCandidates, type CandidateItem } from "@/lib/generator/candidates";
9	import { rankTopN } from "@/lib/generator/rank";
10	import { rerank } from "@/lib/generator/rerank";
11	import { layoutForLook, staggerOrder } from "@/lib/generator/layout";
12	import type {
13	  GenerateResult,
14	  Look,
15	  LookPiece,
16	  UiOccasion,
17	  WeatherPayload,
18	} from "@/lib/generator/types";
19	
20	const DEFAULT_LOCATION = { lat: 52.52, lon: 13.41, label: "Berlin" };
21	
22	function currentSeason(d: Date): string {
23	  const m = d.getMonth();
24	  return m < 2 || m === 11 ? "Winter" : m < 5 ? "Spring" : m < 8 ? "Summer" : "Autumn";
25	}
26	
27	export async function generate(input: {
28	  occasion: UiOccasion;
29	  formality: number | null;
30	  mustColors: string[];
31	  city?: { lat: number; lon: number; label: string };
32	}): Promise<GenerateResult> {
33	  try {
34	    const supabase = await createClient();
35	    const {
36	      data: { user },
37	    } = await supabase.auth.getUser();
38	    if (!user) return { status: "error", message: "Not signed in" };
39	
40	    const { data: profile } = await supabase
41	      .from("profiles")
42	      .select("archetype, location_lat, location_lon, location_label")
43	      .eq("id", user.id)
44	      .single();
45	    const { data: itemsRaw } = await supabase
46	      .from("items")
47	      .select("*")
48	      .eq("user_id", user.id)
49	      .eq("archived", false);
50	    const items = itemsRaw ?? [];
51	    const byId = new Map(items.map((i) => [i.id, i]));
52	
53	    const loc =
54	      input.city ??
55	      (profile?.location_lat != null
56	        ? {
57	            lat: profile.location_lat,
58	            lon: profile.location_lon as number,
59	            label: profile.location_label ?? "Current location",
60	          }
61	        : DEFAULT_LOCATION);
62	
63	    const now = new Date();
64	    const f = await fetchForecast(loc.lat, loc.lon, now.toISOString().slice(0, 16));
65	    const advice = laterAdvice(f.hourly);
66	    const weather: WeatherPayload = {
67	      tempC: f.tempC,
68	      feelsLikeC: f.feelsLikeC,
69	      condition: f.condition,
70	      cityLabel: loc.label,
71	      laterSentence: advice.sentence,
72	      adviceClause: advice.adviceClause,
73	      laterLabel: "Later",
74	      hourly: f.hourly,
75	    };
76	
77	    const candItems: CandidateItem[] = items.map((i) => ({
78	      id: i.id,
79	      category: i.category,
80	      colors: i.colors ?? [],
81	      formality: i.formality,
82	      seasons: i.seasons ?? [],
83	      material: i.material,
84	    }));
85	    const band = applyFormalityOverride(occasionBand(input.occasion), input.formality);
86	    const combos = buildCandidates(candItems, {
87	      band,
88	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
89	      season: currentSeason(now),
90	      excludeItemIds: [],
91	      mustColors: input.mustColors,
92	      maxAccessories: 1,
93	    });
94	    if (combos.length === 0) return { status: "empty", weather };
95	
96	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
97	    const top = rankTopN(combos, { aesthetic, band }, 20);
98	
99	    const { picks } = await rerank({
100	      combos: top.map((t) =>
101	        t.items.map((ci) => {
102	          const it = byId.get(ci.id)!;
103	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
104	        }),
105	      ),
106	      aesthetic,
107	      occasion: input.occasion,
108	      weatherLabel: f.condition,
109	      tempC: f.tempC,
110	    });
111	
112	    const paths = Array.from(
113	      new Set(top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!)))),
114	    );
115	    const signed = await signItemImages(paths);
116	
117	    const looks: Look[] = picks.map((p) => {
118	      const combo = top[p.combo_index]?.items ?? top[0].items;
119	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
120	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
121	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
122	        itemId: d.id,
123	        category: d.category,
124	        subcategory: d.subcategory ?? null,
125	        brand: d.brand ?? null,
126	        name: d.name ?? null,
127	        colors: d.colors ?? [],
128	        cutoutUrl: signed.get(displayPath(d)) ?? "",
129	        slot: slots[idx],
130	      }));
131	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
132	    });
133	
134	    return { status: "ok", weather, looks };
135	  } catch (e) {
136	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
137	  }
138	}
