1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { StylistView, type StylistStatus } from "./stylist-view";
6	import { generate } from "@/app/generate/actions";
7	import { searchCities, type City } from "@/lib/weather/geocode";
8	import type { Look, UiOccasion, WeatherPayload } from "@/lib/generator/types";
9	
10	type Chosen = { lat: number; lon: number; label: string };
11	
12	export function Stylist() {
13	  const router = useRouter();
14	  const [status, setStatus] = useState<StylistStatus>("loading");
15	  const [occasion, setOccasion] = useState<UiOccasion>("everyday");
16	  const [formality, setFormality] = useState<number | null>(null);
17	  const [mustColors, setMustColors] = useState<string[]>([]);
18	  const [city, setCity] = useState<Chosen | null>(null);
19	  const [nonce, setNonce] = useState(0);
20	
21	  const [weather, setWeather] = useState<WeatherPayload | null>(null);
22	  const [looks, setLooks] = useState<Look[]>([]);
23	  const [selectedLook, setSelectedLook] = useState(0);
24	  const [cities, setCities] = useState<City[]>([]);
25	  const [refineOpen, setRefineOpen] = useState(false);
26	
27	  useEffect(() => {
28	    let cancelled = false;
29	    setStatus("loading");
30	    generate({ occasion, formality, mustColors, city: city ?? undefined }).then((res) => {
31	      if (cancelled) return;
32	      if (res.status === "ok") {
33	        setWeather(res.weather);
34	        setLooks(res.looks);
35	        setSelectedLook(0);
36	        setStatus("ok");
37	      } else if (res.status === "empty") {
38	        setWeather(res.weather);
39	        setLooks([]);
40	        setStatus("empty");
41	      } else {
42	        setStatus("error");
43	      }
44	    });
45	    return () => {
46	      cancelled = true;
47	    };
48	  }, [occasion, formality, mustColors, city, nonce]);
49	
50	  return (
51	    <StylistView
52	      status={status}
53	      weather={weather}
54	      looks={looks}
55	      selectedLook={selectedLook}
56	      occasion={occasion}
57	      cities={cities}
58	      refineOpen={refineOpen}
59	      onOccasion={setOccasion}
60	      onOpenRefine={() => setRefineOpen(true)}
61	      onCloseRefine={() => setRefineOpen(false)}
62	      onRefineApply={({ formality: f, mustColors: c }) => {
63	        setFormality(f);
64	        setMustColors(c);
65	        setRefineOpen(false);
66	      }}
67	      onCityChange={(c) => setCity({ lat: c.lat, lon: c.lon, label: c.name })}
68	      onCitySearch={(q) => {
69	        if (q.trim().length < 2) return;
70	        searchCities(q).then(setCities);
71	      }}
72	      onSelectLook={setSelectedLook}
73	      onRetry={() => setNonce((n) => n + 1)}
74	      onOpenItem={(id) => router.push(`/closet/${id}`)}
75	    />
76	  );
77	}
