1	// Open-Meteo Geocoding is NAME-SEARCH ONLY (no reverse endpoint — D8).
2	// We never derive a city name from coordinates.
3	
4	export type City = { name: string; country: string; lat: number; lon: number };
5	
6	type Raw = {
7	  results?: { name: string; country: string; latitude: number; longitude: number }[];
8	};
9	
10	export function mapSearch(raw: Raw): City[] {
11	  return (raw.results ?? []).map((r) => ({
12	    name: r.name,
13	    country: r.country,
14	    lat: r.latitude,
15	    lon: r.longitude,
16	  }));
17	}
18	
19	export function pickLabel(c: City): string {
20	  return c.name;
21	}
22	
23	export async function searchCities(q: string): Promise<City[]> {
24	  const url = `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(q)}&count=5&language=en`;
25	  const res = await fetch(url);
26	  return mapSearch(await res.json());
27	}
