1	import type { HourCell } from "@/lib/generator/types";
2	
3	export const RAIN_CODES = new Set([51, 53, 55, 61, 63, 65, 80, 81, 82, 95, 96, 99]);
4	
5	type Raw = {
6	  current: { temperature_2m: number; apparent_temperature: number; weather_code: number };
7	  hourly: {
8	    time: string[];
9	    temperature_2m: number[];
10	    weather_code: number[];
11	    precipitation_probability: number[];
12	  };
13	};
14	
15	function conditionFor(code: number): string {
16	  if (RAIN_CODES.has(code)) return "Rain";
17	  if (code === 0) return "Clear";
18	  if (code <= 2) return "Partly cloudy";
19	  return "Overcast";
20	}
21	
22	/** "2026-01-14T18:00" → "18:00" */
23	function hhmm(iso: string): string {
24	  return (iso.split("T")[1] ?? "").slice(0, 5);
25	}
26	
27	/** nowIso is INJECTED (pure) — do not call new Date() here. */
28	export function mapForecast(
29	  raw: Raw,
30	  nowIso: string,
31	): { tempC: number; feelsLikeC: number; condition: string; hourly: HourCell[] } {
32	  const times = raw.hourly.time;
33	  let nowIdx = times.findIndex((t) => t >= nowIso); // first hour at/after now
34	  if (nowIdx < 0) nowIdx = 0;
35	
36	  const hourly: HourCell[] = [];
37	  for (let k = 0; k < 4 && nowIdx + k < times.length; k++) {
38	    const i = nowIdx + k;
39	    hourly.push({
40	      hh: hhmm(times[i]),
41	      tempC: Math.round(raw.hourly.temperature_2m[i]),
42	      rain: RAIN_CODES.has(raw.hourly.weather_code[i]),
43	      isNow: k === 0,
44	    });
45	  }
46	
47	  return {
48	    tempC: Math.round(raw.current.temperature_2m),
49	    feelsLikeC: Math.round(raw.current.apparent_temperature),
50	    condition: conditionFor(raw.current.weather_code),
51	    hourly,
52	  };
53	}
54	
55	export async function fetchForecast(lat: number, lon: number, nowIso: string) {
56	  const url =
57	    `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}` +
58	    `&current=temperature_2m,apparent_temperature,weather_code` +
59	    `&hourly=temperature_2m,weather_code,precipitation_probability&forecast_hours=24`;
60	  const res = await fetch(url, { next: { revalidate: 1800 } });
61	  return mapForecast(await res.json(), nowIso);
62	}
