import { roundCoord, resolveLocation, DEFAULT_LOCATION } from "../location";

test("roundCoord snaps to 2dp (~1.1km) so neighbours share one cached forecast URL", () => {
  expect(roundCoord(52.5187234)).toBe(52.52);
  expect(roundCoord(-0.1277583)).toBe(-0.13);
  expect(roundCoord(13.41)).toBe(13.41); // already short — unchanged
  expect(roundCoord(0)).toBe(0);
});

test("client-chosen location wins over everything, carrying its source as the origin", () => {
  const r = resolveLocation({
    input: { lat: 51.5, lon: -0.1, label: "London", source: "city" },
    profile: { location_lat: 48.14, location_lon: 11.58, location_label: "Munich" },
  });
  expect(r).toEqual({ lat: 51.5, lon: -0.1, label: "London", origin: "city" });
});

test("falls back to the profile when there is no client choice", () => {
  const r = resolveLocation({
    profile: { location_lat: 48.14, location_lon: 11.58, location_label: "Munich" },
  });
  expect(r).toEqual({ lat: 48.14, lon: 11.58, label: "Munich", origin: "profile" });
});

test("a profile row with no coords is NOT a location — falls through to the default", () => {
  const r = resolveLocation({
    profile: { location_lat: null, location_lon: null, location_label: null },
  });
  expect(r).toEqual({ ...DEFAULT_LOCATION });
  expect(r.origin).toBe("default");
});

test("no input and no profile → the default", () => {
  expect(resolveLocation({})).toEqual({ ...DEFAULT_LOCATION });
  expect(resolveLocation({ profile: null })).toEqual({ ...DEFAULT_LOCATION });
});

test("a stored location with no label is labelled Current location (we never reverse-geocode)", () => {
  const r = resolveLocation({
    profile: { location_lat: 48.14, location_lon: 11.58, location_label: null },
  });
  expect(r.label).toBe("Current location");
});

// Location resolution — pure. No I/O, no clock.
// We NEVER derive a city name from coordinates: Open-Meteo has no reverse endpoint
// (D8), and third-party reverse geocoders would ship precise user coords off-stack.

/** What we persist to profiles.location_source. */
export type LocationSource = "geo" | "city";
/** Where the location we're using actually came from. */
export type LocationOrigin = LocationSource | "profile" | "default";

export type ResolvedLocation = {
  lat: number;
  lon: number;
  label: string;
  origin: LocationOrigin;
};

export type ProfileLocation = {
  location_lat: number | null;
  location_lon: number | null;
  location_label: string | null;
};

export const DEFAULT_LOCATION: ResolvedLocation = {
  lat: 52.52,
  lon: 13.41,
  label: "Berlin",
  origin: "default",
};

/**
 * 2dp ≈ 1.1km. Raw GPS precision would make every user's forecast URL unique,
 * defeating the 30-minute fetch cache in fetchForecast and burning the
 * Open-Meteo daily request budget. Also stores less precise personal data.
 */
export function roundCoord(n: number): number {
  return Math.round(n * 100) / 100;
}

export function resolveLocation(args: {
  input?: { lat: number; lon: number; label: string; source: LocationSource };
  profile?: ProfileLocation | null;
}): ResolvedLocation {
  const { input, profile } = args;

  if (input) {
    return { lat: input.lat, lon: input.lon, label: input.label, origin: input.source };
  }

  if (profile?.location_lat != null && profile.location_lon != null) {
    return {
      lat: profile.location_lat,
      lon: profile.location_lon,
      label: profile.location_label ?? "Current location",
      origin: "profile",
    };
  }

  return { ...DEFAULT_LOCATION };
}

import { mapForecast, fetchForecast, RAIN_CODES } from "../open-meteo";

const raw = {
  timezone: "Europe/Berlin",
  current: {
    // local time AT THE LOCATION — this is our now-marker, same clock as hourly.time
    time: "2026-01-14T18:00",
    temperature_2m: 14.3,
    apparent_temperature: 12.1,
    weather_code: 3,
  },
  hourly: {
    // 1-hour steps; NOTE now (18:00) is index 2, not 0 — proves forward-slice-from-now
    time: [
      "2026-01-14T16:00", "2026-01-14T17:00", "2026-01-14T18:00", "2026-01-14T19:00",
      "2026-01-14T20:00", "2026-01-14T21:00", "2026-01-14T22:00",
    ],
    temperature_2m: [16, 15, 14, 13, 12, 11, 10],
    weather_code: [3, 3, 3, 3, 3, 61, 61],
    precipitation_probability: [5, 8, 10, 20, 30, 80, 75],
  },
};

test("maps current temp (rounded), feels-like, and condition", () => {
  const w = mapForecast(raw, "2026-01-14T18:00");
  expect(w.tempC).toBe(14);
  expect(w.feelsLikeC).toBe(12);
  expect(w.condition).toMatch(/overcast|cloud/i);
});

test("hourly = 4 forward cells FROM the now index (pre-now excluded), with isNow + per-cell temp + rain", () => {
  const w = mapForecast(raw, "2026-01-14T18:00");
  expect(w.hourly).toHaveLength(4);
  expect(w.hourly[0].hh).toBe("18:00");
  expect(w.hourly[0].isNow).toBe(true);
  expect(w.hourly.map((c) => c.hh)).not.toContain("16:00"); // pre-now hours dropped
  expect(w.hourly.map((c) => c.hh)).not.toContain("17:00");
  expect(w.hourly.find((c) => c.hh === "21:00")!.rain).toBe(true);
  expect(w.hourly.find((c) => c.hh === "21:00")!.tempC).toBe(11); // per-cell temp mapped
});

test("rain weather codes are classified as rain", () => {
  expect(RAIN_CODES.has(61)).toBe(true);
  expect(RAIN_CODES.has(0)).toBe(false);
});

// --- new: timezone correctness -------------------------------------------------

test("with no nowIso, the now-index comes from raw.current.time — NOT the machine clock", () => {
  const w = mapForecast(raw); // no injected now
  expect(w.hourly[0].hh).toBe("18:00");
  expect(w.hourly[0].isNow).toBe(true);
  expect(w.hourly).toHaveLength(4);
});

test("an explicitly injected nowIso still overrides the default", () => {
  const w = mapForecast(raw, "2026-01-14T20:00");
  expect(w.hourly[0].hh).toBe("20:00");
});

test("the resolved IANA timezone is passed through (server-side scheduling needs it)", () => {
  expect(mapForecast(raw).timezone).toBe("Europe/Berlin");
});

test("fetchForecast asks for timezone=auto and ROUNDS coords so the 30-min cache can hit", async () => {
  const calls: string[] = [];
  const fetchMock = vi.fn(async (url: string) => {
    calls.push(url);
    return { json: async () => raw } as unknown as Response;
  });
  vi.stubGlobal("fetch", fetchMock);

  const w = await fetchForecast(52.5187234, 13.4098765);

  expect(calls[0]).toContain("timezone=auto");
  expect(calls[0]).toContain("latitude=52.52");
  expect(calls[0]).toContain("longitude=13.41");
  expect(calls[0]).not.toContain("52.5187234"); // raw precision never reaches the URL
  expect(w.timezone).toBe("Europe/Berlin");

  vi.unstubAllGlobals();
});

