import { occasionBand } from "../rules";
import { buildCandidates, type CandidateItem } from "../candidates";
import type { UiOccasion } from "../types";

// The user's actual 8 items, straight from the local DB.
const items: CandidateItem[] = [
  { id: "b1", category: "Bottoms", subcategory: "Pleated trousers", formality: 3, seasons: ["Spring", "Summer", "Autumn"], material: "Lyocell", colors: ["cream"] } as CandidateItem,
  { id: "b2", category: "Bottoms", formality: 3, seasons: ["Summer", "Spring"], material: "Lyocell", colors: ["charcoal"] },
  { id: "s1", category: "Shoes", formality: 2, seasons: ["Spring", "Summer", "Autumn", "Winter"], material: "leather", colors: ["cream"] },
  { id: "s2", category: "Shoes", formality: 2, seasons: ["Spring", "Summer", "Autumn", "Winter"], material: "leather", colors: ["white"] },
  { id: "t1", category: "Tops", formality: 3, seasons: ["Spring", "Autumn", "Winter", "Summer"], material: "Cotton", colors: ["navy"] },
  { id: "t2", category: "Tops", formality: 3, seasons: ["Spring", "Summer", "Autumn", "Winter"], material: "cotton", colors: ["blue"] },
  { id: "t3", category: "Tops", formality: 3, seasons: ["Autumn", "Winter"], material: "Cotton", colors: ["navy"] },
  { id: "t4", category: "Tops", formality: 3, seasons: ["Spring", "Summer", "Autumn", "Winter"], material: "cotton", colors: ["white"] },
];

const OCCASIONS: UiOccasion[] = ["everyday", "work", "weekend", "evening"];

test("DIAGNOSTIC: which occasions produce zero combos with this closet", () => {
  const report: Record<string, number> = {};
  for (const o of OCCASIONS) {
    const band = occasionBand(o);
    const combos = buildCandidates(items, {
      band,
      weather: { tempC: 24, rain: false }, // today's real weather: warm, dry
      season: "Summer",
      excludeItemIds: [],
      mustColors: [],
      maxAccessories: 1,
    });
    report[`${o} band=[${band[0]},${band[1]}]`] = combos.length;
  }
  console.log("COMBOS PER OCCASION:", JSON.stringify(report, null, 2));

  // Per-category eligibility for the two suspect bands
  for (const o of ["work", "evening"] as UiOccasion[]) {
    const [lo, hi] = occasionBand(o);
    const pass = items.filter((i) => {
      const f = i.formality ?? 3;
      return f >= lo - 0.5 && f <= hi + 0.5 && i.seasons.includes("Summer");
    });
    console.log(
      `${o} [${lo},${hi}] → effective [${lo - 0.5},${hi + 0.5}] → eligible by category:`,
      JSON.stringify(
        ["Tops", "Bottoms", "Shoes"].map((c) => `${c}=${pass.filter((i) => i.category === c).length}`),
      ),
    );
  }
  expect(true).toBe(true);
});

