import { personalBand, applyFormalityOverride } from "../rules";
import { buildCandidates, missingCategory, type CandidateItem } from "../candidates";
import type { UiOccasion } from "../types";

// The user's actual closet + actual onboarding answer, from the local DB.
const items: CandidateItem[] = [
  { id: "b1", category: "Bottoms", colors: ["cream"], formality: 3, seasons: ["Spring", "Summer", "Autumn"], material: "Lyocell" },
  { id: "b2", category: "Bottoms", colors: ["charcoal"], formality: 3, seasons: ["Summer", "Spring"], material: "Lyocell" },
  { id: "s1", category: "Shoes", colors: ["cream"], formality: 2, seasons: ["Spring", "Summer", "Autumn", "Winter"], material: "leather" },
  { id: "s2", category: "Shoes", colors: ["white"], formality: 2, seasons: ["Spring", "Summer", "Autumn", "Winter"], material: "leather" },
  { id: "t1", category: "Tops", colors: ["navy"], formality: 3, seasons: ["Spring", "Autumn", "Winter", "Summer"], material: "Cotton" },
  { id: "t2", category: "Tops", colors: ["blue"], formality: 3, seasons: ["Spring", "Summer", "Autumn", "Winter"], material: "cotton" },
  { id: "t3", category: "Tops", colors: ["navy"], formality: 3, seasons: ["Autumn", "Winter"], material: "Cotton" },
  { id: "t4", category: "Tops", colors: ["white"], formality: 3, seasons: ["Spring", "Summer", "Autumn", "Winter"], material: "cotton" },
];
const profile = { formality_min: 3, formality_max: 3 }; // dress_codes: {Smart casual}
const OCCASIONS: UiOccasion[] = ["everyday", "work", "weekend", "evening"];

function run(o: UiOccasion, formality: number | null, season: string, tempC: number) {
  const band = applyFormalityOverride(personalBand(o, profile), formality);
  const args = {
    band,
    weather: { tempC, rain: false },
    season,
    excludeItemIds: [],
    mustColors: [],
    maxAccessories: 1,
  };
  return { band, n: buildCandidates(items, args).length, missing: missingCategory(items, args) };
}

test("VERIFY: all four occasions now produce outfits in summer", () => {
  const out: Record<string, string> = {};
  for (const o of OCCASIONS) {
    const r = run(o, null, "Summer", 24);
    out[o] = `band=[${r.band[0]},${r.band[1]}] combos=${r.n} missing=${r.missing ?? "-"}`;
    expect(r.n).toBeGreaterThan(0);
  }
  console.log("SUMMER:", JSON.stringify(out, null, 2));
});

test("VERIFY: winter still works with no outerwear in the closet", () => {
  const out: Record<string, string> = {};
  for (const o of OCCASIONS) {
    const r = run(o, null, "Winter", 4);
    out[o] = `band=[${r.band[0]},${r.band[1]}] combos=${r.n} missing=${r.missing ?? "-"}`;
  }
  console.log("WINTER (no coat, 4°C):", JSON.stringify(out, null, 2));
  expect(run("everyday", null, "Winter", 4).n).toBeGreaterThan(0);
});

test("VERIFY: explicitly refining up to black tie correctly reports the real gap", () => {
  const r = run("evening", 5, "Summer", 24);
  console.log("EVENING + Refine formality=5:", JSON.stringify(r));
  expect(r.n).toBe(0);
  expect(r.missing).toBe("Shoes"); // and the screen now says so
});

